export function searchHadiths(q: string) {
  const s = q.trim();
  if (!s) return HADITHS;
  return HADITHS.filter(
    (h) =>
      h.text.includes(s) ||
      h.topics.some((t) => t.includes(s)) ||
      h.book.includes(s) ||
      h.grade.includes(s) ||
      h.number.includes(s)
  );
}

export function getHadithsByCollection(id: string) {
  return HADITHS.filter((h) => h.collection === id);
}

export function getHadithsByTopic(topic: string) {
  return HADITHS.filter((h) => h.topics.includes(topic));
}
